package com.dudleylane.quickfix.fix40;

/** FIX 4.0 Email (35=C). Generated by spec/GeneratorJava.rb. */
public class Email extends Message {
    public static final String MSGTYPE = "C";

    public Email() {
        setHeaderField(35, MSGTYPE);
    }

    private Email(long cPtr) {
        super(cPtr, false);
    }

    /**
     * message as a Email, without copying it: the same engine object, and the view keeps message from being
     * collected. message.delete() ends the view of a message Java made, and a call through it then throws. A
     * callback's message is the engine's, and the engine reuses it once the callback returns, so the view must
     * not outlive the callback; copy it (new Message(message)) to keep it.
     */
    public static Email view(com.dudleylane.quickfix.Message message) {
        return typedView(message, MSGTYPE, "Email", Email::new);
    }
}
